  Ltac after_memcpy HL Hms Hkeep :=
    replace (Z_to_bv 64 921156) with (0xe0e44 : word) by (apply bv_eq; reflexivity);
    eapply srz_msteps; [exact Hh | exact Hlazy | exact Hms |]; clear Hms;
    replace (0xd5e0c : word) with (Z_to_bv 64 0xd5e0c) by (apply bv_eq; reflexivity);
    lazymatch goal with H : regs_ok ?E ?sr ?Rc |- srealizes _ (mkCfg (mkst ?R2 _ _ _) _) _ =>
      pose proof (regs_after_keeps _ (blobs_ev BL) sr Rc R2 callee_kept
                    ltac:(rewrite HL; vm_compute; reflexivity) H Hkeep callee_kept_no0) as HR2;
      rewrite HL in HR2; clear H Hkeep; rename HR2 into HR
    end.

